import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function validateUint(field, token, min) {
  if (!INT_RE.test(token) || BigInt(token) < min) {
    throw new Error(`${field} must be an integer of at least ${min}`)
  }
  return BigInt(token)
}

/**
 * Runs a limiter file (as read from stdin) in the given mode ('replay' or
 * 'summary') and returns the stdout text. Throws LineError on any parse or
 * validation failure, before anything would have been written to stdout.
 */
export function simulate(mode, input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map() // name -> policy instance
  const routes = [] // { prefix, policyNames: [...], policyObjs: [...] }
  const routePrefixes = new Set()
  let seenEvent = false
  let lastTick = null

  const replayLines = []
  const summary = new Map() // key -> { allowed, denied }
  let totalAllowed = 0n
  let totalDenied = 0n

  const wrap = (lineNo, fn) => {
    try {
      return fn()
    } catch (e) {
      if (e instanceof LineError) throw e
      throw new LineError(lineNo, e.message)
    }
  }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) throw new LineError(lineNo, 'declarations must come before the first event')
    } else if (directive !== 'event') {
      throw new LineError(lineNo, `unknown directive ${directive}`)
    }

    wrap(lineNo, () => {
      if (directive === 'bucket') {
        if (tokens.length !== 5) throw new Error('expected bucket <name> <capacity> <refill> <per>')
        const [, name, capTok, refillTok, perTok] = tokens
        if (!NAME_RE.test(name)) throw new Error(`invalid policy name ${name}`)
        const capacity = validateUint('capacity', capTok, 1n)
        const refill = validateUint('refill', refillTok, 0n)
        const per = validateUint('per', perTok, 1n)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        policies.set(name, new TokenBucket(name, capacity, refill, per))
      } else if (directive === 'window') {
        if (tokens.length !== 4) throw new Error('expected window <name> <limit> <span>')
        const [, name, limitTok, spanTok] = tokens
        if (!NAME_RE.test(name)) throw new Error(`invalid policy name ${name}`)
        const limit = validateUint('limit', limitTok, 0n)
        const span = validateUint('span', spanTok, 1n)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        policies.set(name, new SlidingWindow(name, limit, span))
      } else if (directive === 'route') {
        if (tokens.length < 3) throw new Error('expected route <prefix> <policy>...')
        const prefix = tokens[1]
        if (!NAME_RE.test(prefix)) throw new Error(`invalid route prefix ${prefix}`)
        const policyNames = tokens.slice(2)
        const policyObjs = []
        for (const pname of policyNames) {
          const p = policies.get(pname)
          if (!p) throw new Error(`unknown policy ${pname}`)
          policyObjs.push(p)
        }
        if (routePrefixes.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
        routePrefixes.add(prefix)
        routes.push({ prefix, policyObjs })
      } else if (directive === 'event') {
        if (tokens.length !== 3) throw new Error('expected event <tick> <key>')
        const [, tickTok, key] = tokens
        const tick = validateUint('tick', tickTok, 0n)
        if (!NAME_RE.test(key)) throw new Error(`invalid key ${key}`)
        if (lastTick !== null && tick < lastTick) throw new Error(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        seenEvent = true

        let best = null
        for (const r of routes) {
          if (key.startsWith(r.prefix)) {
            if (best === null || r.prefix.length > best.prefix.length) best = r
          }
        }

        let allowed = true
        let denyPolicyName = null
        if (best !== null) {
          for (const p of best.policyObjs) p.advance(tick, key)
          for (const p of best.policyObjs) {
            if (!p.allows(key)) {
              allowed = false
              denyPolicyName = p.name
              break
            }
          }
          if (allowed) {
            for (const p of best.policyObjs) p.record(key, tick)
          }
        }

        if (!summary.has(key)) summary.set(key, { allowed: 0n, denied: 0n })
        const s = summary.get(key)
        if (allowed) {
          s.allowed += 1n
          totalAllowed += 1n
        } else {
          s.denied += 1n
          totalDenied += 1n
        }

        if (mode === 'replay') {
          replayLines.push(allowed ? `${tick} ${key} allow` : `${tick} ${key} deny ${denyPolicyName}`)
        }
      }
    })
  }

  if (mode === 'replay') {
    return replayLines.map((l) => l + '\n').join('')
  }

  const keys = [...summary.keys()].sort()
  let out = ''
  for (const key of keys) {
    const s = summary.get(key)
    out += `${key} allowed=${s.allowed} denied=${s.denied}\n`
  }
  out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  return out
}
"}

