function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  // Synchronous read of fd 0, works for both pipes and files under node.
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

