  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let output
  try {
    output = simulate(mode, input)
  } catch (e) {
    if (e instanceof LineError) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }

  process.stdout.write(output)
  process.exit(0)
}

